// === Tab: mySketch ===
/* 
	evolving lanes #genuary2426 Grow a seed

	https://openprocessing.org/sketch/2157154
	#genuary26 #genuary #creativecoding #generativeart

	https://genuary.art/prompts#jan26
*/

const num = 128;
let clrs, objs;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("multiples lines splitting randomly and following straight directions changing time by time. postprocessing vignette filter and crt lines.")

	pixelDensity(1)
	colorMode(HSB, 100);
	frameRate(30);
	clrs = genColors(num);
	clrs.splice(0, ~~num*0.7)

	const seed = random(year()+month()+day()+hour()+minute()+second());
	console.log(`seed ${seed}`);
	randomSeed(seed)

	objs = [];
	objs.push(new Obj())
}

function draw() {
	// if (frameCount % 45 === 0) objs.push(new Obj()))
	objs = objs.filter((o) => o.alp > 0);
	objs.splice(num, objs.length)

	const bg = color("rgb(8,8,8)");
	background(bg);

	for (let o of objs) {
		o.grow(objs);
		o.show();
	}

	drawBackground(bg);

	// // noLoop() removed for animation
}

function drawBackground(bg) {
	// background(bg);
	push()
	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(
		width/2, height/2, 10, 
		width/2, height/2, max(width, height)*0.65
	);

	// Add three color stops
	gradient.addColorStop(0, color(0, 0, 100, 20));
	gradient.addColorStop(1, color(0, 0, 0, 50)); // bg

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);

	// crt raster lines
	if (true) {
		stroke(0, 0, 100, 50)
		strokeWeight(1.25)
		for (let y = 3; y < height; y += 4) {
			line(0, y, width, y)
		}
	}

	pop();
}

// colors
function genColors(n = 2, keepF = 1, space = 100) {
	arr = [];
	const HUE = ~~random(100)
	const DLT = space / n;
	for (let i = 0; i < n; i++) {
		let clr = color((HUE + i * DLT) % 100, random(85, 110), random(75,111));
		arr.push(clr)
	}
	arr = arr.splice(0, ~~(arr.length * keepF))
	return arr;
}

// interaction
function mousePressed() {
	if (mouseButton === LEFT) {
		setup();
		draw();
	}
}


class Obj {
	constructor(_x, _y) {
		const raster = 10;
		const x = _x || ~~(random(width * 0.1, width * 0.9) / raster) * raster;
		const y = _y || ~~(random(height * 0.1, height * 0.9) / raster) * raster;
		this.clr = random(clrs); // color(255);
		this.alp = 128;
		this.step = raster; // ~~random(2, 4)
		this.poss = [{x, y}];
		this.lifetime = ~~random(45, 135)

		this.dir = createVector(0, -1);
		var num = random(4);
		for (let i = 0; i < num; i++)	this.changeDir();
	}

	grow(objs) {
		if (this.lifetime <= 0) {
			this.alp--;
			return;
		}

		if (random()<0.05) this.seed(objs);
		if (random()<0.1) this.changeDir();
		const i = this.poss.length - 1;
		var x = this.poss[i].x + this.dir.x * this.step;
		var y = this.poss[i].y + this.dir.y * this.step;
		this.poss.push({x, y});
		this.lifetime--;
		if (x < 0 || x > width || y < 0 || y > height) this.lifetime = 0;
	}

	seed(objs) {
		var i = this.poss.length - 1;
		var x = this.poss[i].x;
		var y = this.poss[i].y;
		var num = ~~random(1, 4);
		for (let i = 0; i < num; i++) {
			objs.push(new Obj(x, y))
		}
	}

	changeDir() {
		const heading = this.dir.heading();
		this.dir.setHeading(heading + HALF_PI + (random() < 0.5 ? 1 : -1));
	}

	show() {
		push();
		noFill()
		var clr = this.clr;
		clr.setAlpha(this.alp)
		stroke(clr);
		let px = this.poss[0].x, py = this.poss[0].y;
		for (let p of this.poss) {
			var x = p.x;
			var y = p.y;
			line(px, py, x, y)
			px = x;
			py = y;
		}
		pop();
	}	
}
